// Map renderer (spec §6, CONTRACT §4.13). Outlines are pre-projected Natural Earth land (public domain) generated by
// scripts/make-map.mjs; this module projects points, arrows and labels with the same constants, so everything lines up.
// Nothing is fetched at run time.
import type { MapId } from '../types';
import { f1, svgEl } from './svg';
import { EUROPE_LAND, EUROPE_PROJECTION } from '../generated/map-europe';
import { EUROPE_WEST_LAND, EUROPE_WEST_PROJECTION } from '../generated/map-europe-west';
import { OLDWORLD_LAND, OLDWORLD_PROJECTION } from '../generated/map-oldworld';

export type MapFrameId = 'europe' | 'oldWorld' | 'europeWest';
export interface MapFrameSpec { lonMin: number; lonMax: number; latMin: number; latMax: number; lon0: number; lat0: number }
export const MAP_FRAMES: Readonly<Record<MapFrameId, MapFrameSpec>> = {
  europe: { lonMin: -12, lonMax: 45, latMin: 34, latMax: 72, lon0: 16.5, lat0: 52 },
  oldWorld: { lonMin: -20, lonMax: 145, latMin: -35, latMax: 72, lon0: 62.5, lat0: 30 },
  europeWest: { lonMin: -12, lonMax: 30, latMin: 36, latMax: 66, lon0: 9, lat0: 51 },
};
export const MAP_VIEW = { width: 1000, height: 700 } as const;

/** px = offX + k * ((lon - lon0) * cosLat0 - pxMin); py = offY + k * (latMax - lat). One uniform k, centred. */
export interface MapProjectionConstants { frame: MapFrameId; k: number; offX: number; offY: number; pxMin: number; latMax: number; lon0: number; cosLat0: number }

function frameIdOf(f: MapFrameSpec): MapFrameId {
  const id = (Object.keys(MAP_FRAMES) as MapFrameId[]).find((k) => {
    const g = MAP_FRAMES[k];
    return g.lonMin === f.lonMin && g.lonMax === f.lonMax && g.latMin === f.latMin && g.latMax === f.latMax && g.lon0 === f.lon0 && g.lat0 === f.lat0;
  });
  if (id === undefined) throw new Error('makeProjection: the box is not one of MAP_FRAMES');
  return id;
}

/** Same arithmetic, in the same order, as makeProjection in scripts/make-map.mjs. */
export function makeProjection(f: MapFrameSpec): MapProjectionConstants {
  const frame = frameIdOf(f);
  const cosLat0 = Math.cos((f.lat0 * Math.PI) / 180);
  const pxMin = (f.lonMin - f.lon0) * cosLat0;
  const w = (f.lonMax - f.lonMin) * cosLat0;
  const h = f.latMax - f.latMin;
  const k = Math.min(MAP_VIEW.width / w, MAP_VIEW.height / h);
  return { frame, k, offX: (MAP_VIEW.width - k * w) / 2, offY: (MAP_VIEW.height - k * h) / 2, pxMin, latMax: f.latMax, lon0: f.lon0, cosLat0 };
}

export function project(c: MapProjectionConstants, lat: number, lon: number): { x: number; y: number } {
  return { x: c.offX + c.k * ((lon - c.lon0) * c.cosLat0 - c.pxMin), y: c.offY + c.k * (c.latMax - lat) };
}

/** For europe_pops map_x / map_y, already in §6 projection units: x = (lon - lon0) cos(lat0), y = lat. */
export function projectUnits(c: MapProjectionConstants, ux: number, uy: number): { x: number; y: number } {
  return { x: c.offX + c.k * (ux - c.pxMin), y: c.offY + c.k * (c.latMax - uy) };
}

export interface LatLon { lat: number; lon: number }
/** value: copies per 100 (frequency x 100), the unit of DISTRIBUTION_SCALE_MAX. */
export interface MapPoint extends LatLon { value?: number; label?: string; dx?: number; dy?: number; role?: 'value' | 'true' | 'genetic' | 'marker' }
export type ArrowStyle = 'main' | 'minor' | 'idea';
export interface MapArrow { waypoints: LatLon[]; style: ArrowStyle; wide?: boolean; dashed?: boolean; label?: { text: string; at: number; dx: number; dy: number } }
export interface MapText extends LatLon { text: string; anchor?: 'start' | 'middle' | 'end' }
export interface MapLink { from: LatLon; to: { ux: number; uy: number } }
/** A window onto the 1000 x 700 map space, in viewBox units: the part of the frame a picture shows (see MapSpec.view). */
export interface MapView { x: number; y: number; width: number; height: number }
export interface MapSpec {
  id: MapId; frame: MapFrameId;
  points?: MapPoint[]; arrows?: MapArrow[]; texts?: MapText[]; links?: MapLink[];
  scaleMax?: number;
  sideList?: { label: string; display: string }[];   // drawn by the card (cardView), not in the svg
  /** The window the svg shows (its viewBox). Default: the whole 1000 x 700 map space. Same projection and outline either way, so a
   *  window moves nothing: it only leaves out the part of the frame the drawing does not use (src/maps.ts bandView, Task 20). */
  view?: MapView;
  /** Font size of this map's labels in map units (default MAP_LABEL_FONT_PX). A map whose picture is drawn small on its card asks for
   *  larger words, so they stay readable on a projector (A1, Task 23: a nearly square drawing in a short, wide slot). */
  labelPx?: number;
}

export const DOT_MAX_RADIUS = 14;
/** Font size of every map label (MapText). Task 20's label placer (src/maps.ts) re-exports and measures with it. */
export const MAP_LABEL_FONT_PX = 20;
export const ZERO_RING_RADIUS = 3;
/** Task 24 (controller ruling after the Task 19 review): the smallest filled dot. Area-true, 1 to 8 copies in every 100 would draw a dot of
 *  1.4 to 4 (2.8 for 4 in 100), smaller than the 3 px ring that means "zero": a small number would read as weaker than none. Any value that
 *  does not round to 0 is therefore at least this big, strictly larger than the ring. The printed number stays exact. */
export const MIN_VALUE_RADIUS = 4;
export const ARROW_WIDTH: Readonly<Record<ArrowStyle, number>> = { main: 5, minor: 2.5, idea: 2.5 };
export const WIDE_ARROW_WIDTH = 12;
/** Arrowhead size in stroke widths (the marker is markerWidth x markerHeight of these, markerUnits strokeWidth). */
export const ARROW_HEAD_SIZE = { normal: 3.2, wide: 1.8 } as const;

/** The most an arrow paints beyond its own curve, in viewBox units: half the arrowhead's width (wider than the stroke). */
export function arrowReach(a: MapArrow): number {
  return ((a.wide ? WIDE_ARROW_WIDTH : ARROW_WIDTH[a.style]) * (a.wide ? ARROW_HEAD_SIZE.wide : ARROW_HEAD_SIZE.normal)) / 2;
}
/** `low` and `high` are the two ends of the value scale. Task 24 (same ruling): the light end was #C6DBEF, 1.1 : 1 against the land
 *  (--map-land in src/style.css), so a small number's dot all but vanished; #3182BD is 3.2 : 1 against the land and 4.0 : 1 against the
 *  card background, and every colour between it and #08306B is darker still (tests/map.test.ts pins 3 : 1 at every value).
 *  A1 (Task 23 review, done after Task 24): its grey, `trueDot` (where a group lives) and `link` (the line to the dot where its DNA places
 *  it), was #8C8C8C, 2.6 : 1 against the land, so the lines and the small dots faded into it. #707070 is 3.8 : 1 against the land and
 *  4.7 : 1 against the card background; the blue `geneticDot` is unchanged (4.0 : 1 and 5.0 : 1). */
export const MAP_COLOURS = {
  arrow: '#9B2226', ink: '#1A1A1A', halo: '#FFFFFF', trueDot: '#707070', geneticDot: '#0072B2', link: '#707070',
  ring: '#08519C', low: '#3182BD', high: '#08306B',
} as const;

/** Same rounding as formatCopies (Task 10): one decimal when scaleMax < 100 (TYK2), whole copies otherwise. */
export function roundsToZero(value: number, scaleMax: number): boolean {
  const scale = scaleMax < 100 ? 10 : 1;
  return !(value > 0) || Math.round(value * scale) === 0;
}

/** Spec §6: radius = 14 sqrt(value / scaleMax) (area-true, capped at the scale); a value that rounds to 0 is a 3 px ring. Task 24: no
 *  value that does not round to 0 is drawn smaller than MIN_VALUE_RADIUS (a bigger value never gets a smaller dot). */
export function dotRadius(value: number, scaleMax: number): number {
  if (roundsToZero(value, scaleMax)) return ZERO_RING_RADIUS;
  return Math.max(MIN_VALUE_RADIUS, DOT_MAX_RADIUS * Math.sqrt(Math.min(value, scaleMax) / scaleMax));
}

/** One sequential scale, light to dark blue, by the share of the scale's maximum. */
export function valueColour(value: number, scaleMax: number): string {
  const t = Math.sqrt(Math.max(0, Math.min(1, value / scaleMax)));
  const mix = (a: string, b: string, i: number): number => Math.round(parseInt(a.slice(i, i + 2), 16) * (1 - t) + parseInt(b.slice(i, i + 2), 16) * t);
  return `#${[1, 3, 5].map((i) => mix(MAP_COLOURS.low, MAP_COLOURS.high, i).toString(16).padStart(2, '0')).join('').toUpperCase()}`;
}

export interface XY { x: number; y: number }
/** One cubic Bézier of a Catmull–Rom curve: from `from` to `to` with control points c1 and c2. */
export interface CurveSegment { from: XY; c1: XY; c2: XY; to: XY }

/** The cubic Béziers of the smooth Catmull–Rom curve through the points (none for fewer than two points). */
export function catmullRomSegments(pts: readonly XY[]): CurveSegment[] {
  const out: CurveSegment[] = [];
  for (let i = 0; i < pts.length - 1; i++) {
    const p0 = pts[i - 1] ?? pts[i]!;
    const p1 = pts[i]!;
    const p2 = pts[i + 1]!;
    const p3 = pts[i + 2] ?? p2;
    out.push({
      from: p1,
      c1: { x: p1.x + (p2.x - p0.x) / 6, y: p1.y + (p2.y - p0.y) / 6 },
      c2: { x: p2.x - (p3.x - p1.x) / 6, y: p2.y - (p3.y - p1.y) / 6 },
      to: p2,
    });
  }
  return out;
}

/** A smooth Catmull–Rom curve through the points, as cubic Béziers ("M … C …"); two points give a straight line. */
export function catmullRomPath(pts: readonly XY[]): string {
  if (pts.length === 0) return '';
  const first = pts[0]!;
  if (pts.length === 1) return `M${f1(first.x)} ${f1(first.y)}`;
  if (pts.length === 2) return `M${f1(first.x)} ${f1(first.y)}L${f1(pts[1]!.x)} ${f1(pts[1]!.y)}`;
  let d = `M${f1(first.x)} ${f1(first.y)}`;
  for (const s of catmullRomSegments(pts)) {
    d += `C${f1(s.c1.x)} ${f1(s.c1.y)} ${f1(s.c2.x)} ${f1(s.c2.y)} ${f1(s.to.x)} ${f1(s.to.y)}`;
  }
  return d;
}

const BASES: Readonly<Record<MapFrameId, { land: readonly string[]; projection: MapProjectionConstants }>> = {
  europe: { land: EUROPE_LAND, projection: EUROPE_PROJECTION },
  oldWorld: { land: OLDWORLD_LAND, projection: OLDWORLD_PROJECTION },
  europeWest: { land: EUROPE_WEST_LAND, projection: EUROPE_WEST_PROJECTION },
};

/** The outline and the projection constants of a frame (points and outlines share one transform). */
export function mapBase(frame: MapFrameId): { land: readonly string[]; projection: MapProjectionConstants } {
  return BASES[frame];
}

/** The halo is a fifth of the font size: 4 units at the default 20. */
function label(x: number, y: number, text: string, anchor: 'start' | 'middle' | 'end', fontPx: number): SVGTextElement {
  return svgEl('text', {
    class: 'map-label', x, y, 'text-anchor': anchor, 'font-size': fontPx, 'font-weight': '600', fill: MAP_COLOURS.ink,
    stroke: MAP_COLOURS.halo, 'stroke-width': fontPx / 5, 'stroke-linejoin': 'round', 'paint-order': 'stroke',
  }, text);
}

/**
 * The part of the frame's box that the view shows: the rect the frame outline is drawn on. The outline is a 1 px stroke centred on
 * that rect's edge, and the viewBox (or a window) usually ends exactly on that edge, so half of the stroke lies outside it: every
 * frame is height- or width-limited, so its box touches the viewBox on one axis, and the svg clipped that half (Task 19 review).
 * The svg now lets it show (plots.css: .map-svg { overflow: visible }); in a window it is drawn outside the window's clip.
 */
export function frameOutline(c: MapProjectionConstants, boxW: number, boxH: number, view: MapView): MapView {
  const left = Math.max(c.offX, view.x);
  const top = Math.max(c.offY, view.y);
  const right = Math.min(c.offX + boxW, view.x + view.width);
  const bottom = Math.min(c.offY + boxH, view.y + view.height);
  return { x: left, y: top, width: right - left, height: bottom - top };
}

/** Spec §6 drawing: land var(--map-land), sea = card background, 0.6 px coast, no borders, labels with a halo. */
export function renderMap(svg: SVGSVGElement, spec: MapSpec): void {
  const { land, projection: c } = mapBase(spec.frame);
  const f = MAP_FRAMES[spec.frame];
  const boxW = c.k * (f.lonMax - f.lonMin) * c.cosLat0;
  const boxH = c.k * (f.latMax - f.latMin);
  const view = spec.view ?? { x: 0, y: 0, width: MAP_VIEW.width, height: MAP_VIEW.height };
  const fontPx = spec.labelPx ?? MAP_LABEL_FONT_PX;
  svg.setAttribute('viewBox', `${view.x} ${view.y} ${view.width} ${view.height}`);
  svg.setAttribute('preserveAspectRatio', 'xMidYMid meet');
  svg.classList.add('map-svg');
  svg.setAttribute('data-map', spec.id);
  svg.setAttribute('data-frame', spec.frame);
  svg.setAttribute('aria-hidden', 'true');       // everything a map says is also in its card's text
  svg.replaceChildren();

  const prefix = `map-${spec.id}`;
  const defs = svgEl('defs');
  const markers = new Map<string, string>();
  const markerFor = (a: MapArrow): string => {
    const key = `${a.style}${a.wide ? '-wide' : ''}`;
    let id = markers.get(key);
    if (id === undefined) {
      id = `${prefix}-head-${key}`;
      const size = a.wide ? ARROW_HEAD_SIZE.wide : ARROW_HEAD_SIZE.normal;
      const m = svgEl('marker', { id, viewBox: '0 0 10 10', refX: 7, refY: 5, markerWidth: size, markerHeight: size, orient: 'auto', markerUnits: 'strokeWidth' });
      m.append(svgEl('path', { d: 'M0 0L10 5L0 10Z', fill: MAP_COLOURS.arrow }));
      defs.append(m);
      markers.set(key, id);
    }
    return id;
  };

  const sea = svgEl('rect', { class: 'map-sea', x: c.offX, y: c.offY, width: boxW, height: boxH });
  const landG = svgEl('g', { class: 'map-land' });
  for (const d of land) landG.append(svgEl('path', { d, 'fill-rule': 'evenodd' }));
  const outline = frameOutline(c, boxW, boxH, view);
  const frame = svgEl('rect', { class: 'map-frame', x: outline.x, y: outline.y, width: outline.width, height: outline.height, fill: 'none' });

  const linksG = svgEl('g', { class: 'map-links' });
  for (const l of spec.links ?? []) {
    const a = project(c, l.from.lat, l.from.lon);
    const b = projectUnits(c, l.to.ux, l.to.uy);
    const g = svgEl('g', { class: 'map-link' });
    g.append(svgEl('line', { x1: a.x, y1: a.y, x2: b.x, y2: b.y, stroke: MAP_COLOURS.link, 'stroke-width': 1, 'vector-effect': 'non-scaling-stroke' }));
    g.append(svgEl('circle', { class: 'map-dot map-dot--true', cx: a.x, cy: a.y, r: 4, fill: MAP_COLOURS.trueDot }));
    g.append(svgEl('circle', { class: 'map-dot map-dot--genetic', cx: b.x, cy: b.y, r: 5, fill: MAP_COLOURS.geneticDot }));
    linksG.append(g);
  }

  const labels: SVGTextElement[] = [];
  const arrowsG = svgEl('g', { class: 'map-arrows' });
  for (const a of spec.arrows ?? []) {
    const pts = a.waypoints.map((w) => project(c, w.lat, w.lon));
    const path = svgEl('path', {
      class: `map-arrow map-arrow--${a.style}`, 'data-style': a.style, d: catmullRomPath(pts), fill: 'none',
      stroke: MAP_COLOURS.arrow, 'stroke-width': a.wide ? WIDE_ARROW_WIDTH : ARROW_WIDTH[a.style],
      'stroke-linecap': 'round', 'stroke-linejoin': 'round', 'marker-end': `url(#${markerFor(a)})`,
    });
    if (a.wide) {
      path.setAttribute('data-wide', 'true');
      path.setAttribute('stroke-opacity', '0.75');
    }
    if (a.style === 'idea' || a.dashed === true) path.setAttribute('stroke-dasharray', '9 7');
    arrowsG.append(path);
    if (a.label && pts.length > 0) {
      const p = pts[Math.max(0, Math.min(pts.length - 1, Math.trunc(a.label.at)))]!;
      labels.push(label(p.x + a.label.dx, p.y + a.label.dy, a.label.text, 'start', fontPx));
    }
  }

  const dotsG = svgEl('g', { class: 'map-points' });
  const max = spec.scaleMax ?? 100;
  for (const p of spec.points ?? []) {
    const q = project(c, p.lat, p.lon);
    const role = p.role ?? (p.value !== undefined ? 'value' : 'marker');
    if (role === 'value' && p.value !== undefined) {
      const zero = roundsToZero(p.value, max);
      const r = dotRadius(p.value, max);
      dotsG.append(svgEl('circle', zero
        ? { class: 'map-dot map-dot--zero', cx: q.x, cy: q.y, r, fill: 'none', stroke: MAP_COLOURS.ring, 'stroke-width': 1.5, 'data-value': String(p.value) }
        : { class: 'map-dot map-dot--value', cx: q.x, cy: q.y, r, fill: valueColour(p.value, max), stroke: MAP_COLOURS.halo, 'stroke-width': 1, 'data-value': String(p.value) }));
    } else if (role === 'true' || role === 'genetic') {
      dotsG.append(svgEl('circle', {
        class: `map-dot map-dot--${role}`, cx: q.x, cy: q.y, r: role === 'true' ? 4 : 5, fill: role === 'true' ? MAP_COLOURS.trueDot : MAP_COLOURS.geneticDot,
      }));
    } else {
      dotsG.append(svgEl('circle', { class: 'map-dot map-dot--marker', cx: q.x, cy: q.y, r: 5, fill: MAP_COLOURS.ink, stroke: MAP_COLOURS.halo, 'stroke-width': 1.5 }));
    }
    if (p.label !== undefined) labels.push(label(q.x + (p.dx ?? 8), q.y + (p.dy ?? -8), p.label, 'start', fontPx));
  }
  for (const t of spec.texts ?? []) {
    const q = project(c, t.lat, t.lon);
    labels.push(label(q.x, q.y, t.text, t.anchor ?? 'middle', fontPx));
  }
  const labelsG = svgEl('g', { class: 'map-labels' });
  labelsG.append(...labels);

  if (spec.view === undefined) {
    svg.append(defs, sea, landG, frame, linksG, arrowsG, dotsG, labelsG);
    return;
  }
  // A window: the svg's own box may be taller or wider than the window's shape (a card gives it whatever room is left), and an svg
  // draws the whole of its box, not just its viewBox. The clip keeps the rest of the frame out of any such leftover room. The frame
  // outline sits on the window's edge, so it is drawn above the clipped group, where its outer half is not cut off.
  const clipId = `${prefix}-view`;
  const clip = svgEl('clipPath', { id: clipId });
  clip.append(svgEl('rect', { x: view.x, y: view.y, width: view.width, height: view.height }));
  defs.append(clip);
  const windowG = svgEl('g', { class: 'map-window', 'clip-path': `url(#${clipId})` });
  windowG.append(sea, landG, linksG, arrowsG, dotsG, labelsG);
  svg.append(defs, windowG, frame);
}
